constraints:
1 ≤ n*m ≤ 10^{6}

expected time complexity: O(n*m)
expected auxiliary space: O(n*m)

standard_solution_code:
class Solution:

	def uniquePaths(self, n, m, grid):
		dp = grid
		for i in range(n):
			for j in range(m):
				if i == 0 and j == 0:
					continue
				if grid[i][j] == 0:
					continue
				else:
					up = 0
					down = 0
					if i > 0:
						up = dp[i - 1][j]
					if j > 0:
						down = dp[i][j - 1]
					dp[i][j] = up + down
		return dp[-1][-1] % (10 ** 9 + 7)
